<?php
namespace App\Http\Controllers;
use App\Models\Admission;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;use Illuminate\Validation\Rule;use Throwable;
class AdmissionController extends Controller{
public function store(Request $request):JsonResponse{$validated=$request->validate([
'full_name'=>['required','string','max:150'],'guardian_name'=>['required','string','max:150'],'cnic_bform'=>['required','string','max:30','unique:admissions,cnic_bform'],'date_of_birth'=>['required','date','before:today'],'gender'=>['required',Rule::in(['male','female','other'])],'phone'=>['required','string','max:30'],'email'=>['required','email','max:150'],'address'=>['required','string','max:1000'],'program'=>['required',Rule::in(['BS Nursing','BS Midwifery','LHV','CNA','CMW'])],'previous_qualification'=>['required','string','max:150'],'marks_obtained'=>['required','numeric','min:0'],'total_marks'=>['required','numeric','gt:0'],'percentage'=>['required','numeric','between:0,100'],'cnic_document'=>['required','file','mimes:pdf,jpg,jpeg,png','max:5120'],'educational_documents'=>['required','file','mimes:pdf,jpg,jpeg,png','max:10240'],'photo'=>['required','image','mimes:jpg,jpeg,png','max:2048'],'notes'=>['nullable','string','max:2000']]);
$stored=[];DB::beginTransaction();try{$validated['user_id']=$request->user()->id;$stored[]=$validated['cnic_document_path']=$request->file('cnic_document')->store('admissions/cnic','public');$stored[]=$validated['educational_documents_path']=$request->file('educational_documents')->store('admissions/education','public');$stored[]=$validated['photo_path']=$request->file('photo')->store('admissions/photos','public');unset($validated['cnic_document'],$validated['educational_documents'],$validated['photo']);$admission=Admission::create($validated);DB::commit();return response()->json(['message'=>'Application submitted successfully. Our admissions team will review it.','data'=>['id'=>$admission->id,'status'=>$admission->status]],201);}catch(Throwable $e){DB::rollBack();foreach($stored as $path)Storage::disk('public')->delete($path);report($e);return response()->json(['message'=>'Application could not be saved. Please try again.'],500);}}
}
